(7350179, 1149496, 113016, '<td valign="top">sorry, for me doesn''t fit the challenge of a portrait.  4</td>', 'sorry, for me doesn''t fit the challenge of a portrait.  4', '2015-05-13 01:57:41.000000', NULL, 1),
