(7351532, 1149759, 135744, '<td valign="top">Now this is something different and I love it. Really love the contrast in the direction of the hair and the smoke. Well done on a great job.</td>', 'Now this is something different and I love it. Really love the contrast in the direction of the hair and the smoke. Well done on a great job.', '2015-05-19 16:06:24.000000', NULL, 1),
(7351533, 1149749, 135744, '<td valign="top">Lol what a cute and funny expression.</td>', 'Lol what a cute and funny expression.', '2015-05-19 16:07:13.000000', NULL, 1),
(7351535, 1149766, 94815, '<td valign="top">My favorite of the challenge. I would have to work quite a while to convey in words why this is such a penetratingly dramatic standout to me, but suffice to say it is well done in every way with one caveat: those unnecessary and very distracting bars which have become an affectation among some DPCers. 8</td>', 'My favorite of the challenge. I would have to work quite a while to convey in words why this is such a penetratingly dramatic standout to me, but suffice to say it is well done in every way with one caveat: those unnecessary and very distracting bars which have become an affectation among some DPCers. 8', '2015-05-19 16:09:44.000000', NULL, 1),
(7351536, 1149585, 135744, '<td valign="top">What a character! Looks a bit French to me. Guess he is not keen on dentists. My grandad is the same and has about one more tooth than George.</td>', 'What a character! Looks a bit French to me. Guess he is not keen on dentists. My grandad is the same and has about one more tooth than George.', '2015-05-19 16:09:58.000000', NULL, 1),
(7351537, 1149755, 94815, '<td valign="top">Appealingly cute. voted earlier</td>', 'Appealingly cute. voted earlier', '2015-05-19 16:10:25.000000', NULL, 1),
(7351538, 1149592, 135744, '<td valign="top">Looking good mum. The background is a bit distracting to me but the face is very nicely captured indeed.</td>', 'Looking good mum. The background is a bit distracting to me but the face is very nicely captured indeed.', '2015-05-19 16:11:17.000000', NULL, 1),
(7351539, 1149751, 94815, '<td valign="top">Very pretty and well photographed subject but I find both foreground and background colors to be problematic. voted earlier</td>', 'Very pretty and well photographed subject but I find both foreground and background colors to be problematic. voted earlier', '2015-05-19 16:12:53.000000', NULL, 1),
(7351540, 1149453, 94815, '<td valign="top">Well done image conveying a likeable subject. voted earlier</td>', 'Well done image conveying a likeable subject. voted earlier', '2015-05-19 16:13:44.000000', NULL, 1),
(7351542, 1149777, 94815, '<td valign="top">But its the colors in the face, especially the contrasting eyes and lips that make the shot. Did you try the hair swept behind her shoulders to provide more neck and shoulders exposure? voted earlier</td>', 'But its the colors in the face, especially the contrasting eyes and lips that make the shot. Did you try the hair swept behind her shoulders to provide more neck and shoulders exposure? voted earlier', '2015-05-19 16:18:04.000000', NULL, 1),
(7351543, 1149760, 94815, '<td valign="top">Mr cool. I love the eye.</td>', 'Mr cool. I love the eye.', '2015-05-19 16:19:26.000000', NULL, 1),
